1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 520px; margin: 40px auto; padding: 0 16px; }
11	  h1 { font-size: 1.6rem; margin: 0 0 16px; }
12	  form { display: flex; gap: 8px; margin-bottom: 16px; }
13	  input { flex: 1; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: 10px 14px; font: inherit; border: 0; border-radius: 6px; background: #2b6cb0; color: #fff; cursor: pointer; }
15	  ul { list-style: none; margin: 0; padding: 0; }
16	  li { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: #fff; border: 1px solid #e3e3e3; border-radius: 6px; margin-bottom: 8px; }
17	  li span { flex: 1; word-break: break-word; }
18	  li button { background: #c53030; padding: 6px 10px; font-size: 0.9rem; }
19	  li input[type="checkbox"] { flex: none; width: 18px; height: 18px; margin: 0; }
20	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
21	  input[type="date"] { flex: none; }
22	  li .due { flex: none; font-size: 0.85rem; color: #555; }
23	  select { flex: none; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
24	  li .priority { flex: none; font-size: 0.85rem; color: #555; }
25	  li[data-overdue="true"] { border-color: #c53030; background: #fff5f5; }
26	  li[data-overdue="true"] .due { color: #c53030; font-weight: 600; }
27	  .search { display: block; width: 100%; margin-bottom: 16px; }
28	  li .edit { padding: 4px 8px; }
29	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
30	  .filters button { background: #e2e8f0; color: #222; padding: 6px 12px; font-size: 0.9rem; }
31	  .filters button[aria-pressed="true"] { background: #2b6cb0; color: #fff; }
32	  .bulk { display: flex; gap: 8px; margin-top: 8px; }
33	  .bulk button { background: #e2e8f0; color: #222; padding: 6px 12px; font-size: 0.9rem; }
34	</style>
35	</head>
36	<body>
37	<main>
38	  <h1>Todos</h1>
39	  <form id="todo-form">
40	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
41	    <input data-testid="todo-due" type="date" aria-label="Due date">
42	    <select data-testid="todo-priority" aria-label="Priority">
43	      <option value="low">Low</option>
44	      <option value="med" selected>Med</option>
45	      <option value="high">High</option>
46	    </select>
47	    <button data-testid="todo-add" type="submit">Add</button>
48	  </form>
49	  <input class="search" data-testid="search-input" type="search" placeholder="Search todos" autocomplete="off" aria-label="Search todos">
50	  <div class="filters">
51	    <button data-testid="filter-all" data-filter="all" type="button" aria-pressed="true">All</button>
52	    <button data-testid="filter-active" data-filter="active" type="button" aria-pressed="false">Active</button>
53	    <button data-testid="filter-completed" data-filter="completed" type="button" aria-pressed="false">Completed</button>
54	  </div>
55	  <ul data-testid="todo-list"></ul>
56	  <div class="bulk">
57	    <button data-testid="bulk-mark-all" type="button">Mark all complete</button>
58	    <button data-testid="bulk-clear-completed" type="button">Clear completed</button>
59	  </div>
60	</main>
61	<script>
62	  var STORAGE_KEY = 'todos';
63	  var form = document.getElementById('todo-form');
64	  var input = document.querySelector('[data-testid="todo-input"]');
65	  var dueInput = document.querySelector('[data-testid="todo-due"]');
66	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
67	  var list = document.querySelector('[data-testid="todo-list"]');
68	  var filterButtons = document.querySelectorAll('[data-filter]');
69	  var searchInput = document.querySelector('[data-testid="search-input"]');
70	  var todos = loadTodos();
71	  var currentFilter = 'all';
72	  var searchTerm = '';
73	
74	  // [REQ-001]
75	  function loadTodos() {
76	    try {
77	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
78	      return Array.isArray(data) ? data : [];
79	    } catch (e) {
80	      return [];
81	    }
82	  }
83	
84	  // [REQ-001]
85	  function saveTodos() {
86	    try {
87	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
88	    } catch (e) {}
89	  }
90	
91	  // [REQ-001]
92	  function makeId() {
93	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
94	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
95	  }
96	
97	  // [REQ-003] Due dates are plain local YYYY-MM-DD strings; never parsed through UTC.
98	  function normalizeDue(value) {
99	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
100	  }
101	
102	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD.
103	  function localToday(now) {
104	    now = now || new Date();
105	    var m = String(now.getMonth() + 1).padStart(2, '0');
106	    var d = String(now.getDate()).padStart(2, '0');
107	    return now.getFullYear() + '-' + m + '-' + d;
108	  }
109	
110	  // [REQ-003] Overdue = due date strictly before today's local date (date-only string compare).
111	  function isOverdue(due, today) {
112	    return !!due && due < today;
113	  }
114	
115	  // [REQ-004] Priority is low, med or high; anything else (including missing) is med.
116	  function normalizePriority(value) {
117	    return value === 'low' || value === 'high' ? value : 'med';
118	  }
119	
120	  // [REQ-001] [REQ-003] [REQ-004]
121	  function addTodo(text, due, priority) {
122	    text = text.trim();
123	    if (!text) return;
124	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) });
125	    saveTodos();
126	    render();
127	  }
128	
129	  // [REQ-001]
130	  function deleteTodo(id) {
131	    todos = todos.filter(function (t) { return t.id !== id; });
132	    saveTodos();
133	    render();
134	  }
135	
136	  // [REQ-002]
137	  function toggleTodo(id) {
138	    todos.forEach(function (t) {
139	      if (t.id === id) t.completed = !t.completed;
140	    });
141	    saveTodos();
142	    render();
143	  }
144	
145	  // [REQ-009] Complete every todo. The array is not reordered, so insertion order still breaks priority ties.
146	  function markAllComplete() {
147	    todos.forEach(function (t) { t.completed = true; });
148	    saveTodos();
149	    render();
150	  }
151	
152	  // [REQ-009] Remove every completed todo; active todos keep their order.
153	  function clearCompleted() {
154	    todos = todos.filter(function (t) { return !t.completed; });
155	    saveTodos();
156	    render();
157	  }
158	
159	  // [REQ-005] Highest priority first; insertion order within the same priority. Does not mutate items.
160	  function byPriority(items) {
161	    var rank = { high: 0, med: 1, low: 2 };
162	    return items
163	      .map(function (t, i) { return { t: t, i: i }; })
164	      .sort(function (a, b) {
165	        return (rank[normalizePriority(a.t.priority)] - rank[normalizePriority(b.t.priority)]) || (a.i - b.i);
166	      })
167	      .map(function (x) { return x.t; });
168	  }
169	
170	  // [REQ-007] Case-insensitive substring match; an empty term matches everything.
171	  function matchesSearch(text, term) {
172	    return String(text).toLowerCase().indexOf(String(term || '').toLowerCase()) !== -1;
173	  }
174	
175	  // [REQ-007] Replace a todo's text. Blank text keeps the old text.
176	  function editTodo(id, text) {
177	    text = String(text).trim();
178	    if (!text) return render();
179	    todos.forEach(function (t) {
180	      if (t.id === id) t.text = text;
181	    });
182	    saveTodos();
183	    render();
184	  }
185	
186	  // [REQ-002] [REQ-005] [REQ-007] Search narrows the list; then active first, completed below, by priority and insertion order.
187	  function visibleTodos(items, filter, term) {
188	    items = items.filter(function (t) { return matchesSearch(t.text, term); });
189	    var active = byPriority(items.filter(function (t) { return !t.completed; }));
190	    var done = byPriority(items.filter(function (t) { return !!t.completed; }));
191	    if (filter === 'active') return active;
192	    if (filter === 'completed') return done;
193	    return active.concat(done);
194	  }
195	
196	  // [REQ-002]
197	  function setFilter(filter) {
198	    currentFilter = filter;
199	    render();
200	  }
201	
202	  // [REQ-001] [REQ-002] [REQ-003] [REQ-004] [REQ-006] Priority shown as plain text, no colour coding.
203	  function render() {
204	    var today = localToday();
205	    list.textContent = '';
206	    filterButtons.forEach(function (btn) {
207	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
208	    });
209	    visibleTodos(todos, currentFilter, searchTerm).forEach(function (todo) {
210	      var li = document.createElement('li');
211	      li.setAttribute('data-testid', 'todo-item');
212	      li.setAttribute('data-completed', String(!!todo.completed));
213	      li.setAttribute('data-overdue', String(isOverdue(normalizeDue(todo.due), today)));
214	      li.setAttribute('data-priority', normalizePriority(todo.priority));
215	      li.dataset.id = todo.id;
216	
217	      var toggle = document.createElement('input');
218	      toggle.type = 'checkbox';
219	      toggle.setAttribute('data-testid', 'todo-toggle');
220	      toggle.setAttribute('aria-label', 'Mark complete');
221	      toggle.checked = !!todo.completed;
222	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
223	
224	      var span = document.createElement('span');
225	      span.setAttribute('data-testid', 'todo-text');
226	      span.textContent = todo.text;
227	      span.addEventListener('dblclick', function () { startEdit(span, todo); });
228	
229	      var del = document.createElement('button');
230	      del.type = 'button';
231	      del.setAttribute('data-testid', 'todo-delete');
232	      del.textContent = 'Delete';
233	      del.addEventListener('click', function () { deleteTodo(todo.id); });
234	
235	      li.appendChild(toggle);
236	      li.appendChild(span);
237	      var priority = document.createElement('span');
238	      priority.className = 'priority';
239	      priority.textContent = { high: 'High', med: 'Med', low: 'Low' }[normalizePriority(todo.priority)];
240	      li.appendChild(priority);
241	      if (normalizeDue(todo.due)) {
242	        var due = document.createElement('span');
243	        due.className = 'due';
244	        due.setAttribute('data-testid', 'todo-due-label');
245	        due.textContent = 'Due ' + todo.due;
246	        li.appendChild(due);
247	      }
248	      li.appendChild(del);
249	      list.appendChild(li);
250	    });
251	  }
252	
253	  // [REQ-007] Double-click turns the text into a field. Enter or blur commits; Escape cancels.
254	  function startEdit(span, todo) {
255	    var field = document.createElement('input');
256	    field.type = 'text';
257	    field.className = 'edit';
258	    field.setAttribute('data-testid', 'todo-edit');
259	    field.setAttribute('aria-label', 'Edit todo');
260	    field.value = todo.text;
261	    var finished = false;
262	    function finish(commit) {
263	      if (finished) return;
264	      finished = true;
265	      if (commit) editTodo(todo.id, field.value);
266	      else render();
267	    }
268	    field.addEventListener('keydown', function (e) {
269	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
270	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
271	    });
272	    field.addEventListener('blur', function () { finish(true); });
273	    span.replaceWith(field);
274	    field.focus();
275	    field.select();
276	  }
277	
278	  // [REQ-007]
279	  searchInput.addEventListener('input', function () {
280	    searchTerm = searchInput.value;
281	    render();
282	  });
283	
284	  // [REQ-009]
285	  document.querySelector('[data-testid="bulk-mark-all"]').addEventListener('click', markAllComplete);
286	  document.querySelector('[data-testid="bulk-clear-completed"]').addEventListener('click', clearCompleted);
287	
288	  filterButtons.forEach(function (btn) {
289	    btn.addEventListener('click', function () { setFilter(btn.dataset.filter); });
290	  });
291	
292	  form.addEventListener('submit', function (e) {
293	    e.preventDefault();
294	    addTodo(input.value, dueInput.value, priorityInput.value);
295	    input.value = '';
296	    dueInput.value = '';
297	    priorityInput.value = 'med';
298	    input.focus();
299	  });
300	
301	  render();
302	</script>
303	</body>
304	</html>
